def mark_skipped_by_config(items, marker_name, selected_value):
    """Apply skip marks based on the testing configuration of a particular run.

    pytest_collection_modifyitems() calls this function for each entry
    on CONFIG_SKIP_MARKERS.
    """
    try:
        _, known_values, value_description = CONFIG_SKIP_MARKERS[marker_name]
    except KeyError:
        raise pytest.UsageError(f"Unknown config skip marker: {marker_name}") from None

    for item in items:
        for marker in item.iter_markers(marker_name):
            unknown_values = [
                value for value in marker.args if value not in known_values
            ]
            if not marker.args or unknown_values:
                supplied_values = (
                    ", ".join(repr(value) for value in marker.args) or "none"
                )
                expected_values = ", ".join(repr(value) for value in known_values)
                raise pytest.UsageError(
                    f"{item.nodeid}: {marker_name} has unknown {value_description} "
                    f"value(s) {supplied_values}; expected one or more of {expected_values}"
                )

            if selected_value in marker.args:
                reason = marker.kwargs.get(
                    "reason", f"skipped on '{selected_value}' {value_description}"
                )
                item.add_marker(pytest.mark.skip(reason=reason))
                break


def pytest_collection_modifyitems(config, items):
    """Apply skip marker during collection.

    Implementing skips this way offers two benefits:
    - It allows to verify that the skip parameters are valid (no typos).
    - Skips are applied before any fixture is initialized, so only fixtures
    that are needed for each testing config are initialized.

    Pytest calls this hook after collecting test items, but before initializing anything.
    - It converts the custom profile and database-type markers into Pytest skips,
    - Also skips tests when there are no valid s3 credentials or the DuckLake extension is unavailable.
    """
    for marker_name, (option_name, _, _) in CONFIG_SKIP_MARKERS.items():
        mark_skipped_by_config(items, marker_name, config.getoption(option_name))

    skip_s3 = None
    # Skip the S3 tests if the secrets are not available
    if not (
        os.getenv("S3_MD_ORG_KEY")
        and os.getenv("S3_MD_ORG_REGION")
        and os.getenv("S3_MD_ORG_SECRET")
    ):
        skip_s3 = pytest.mark.skip(reason="need S3 credentials to run this test")

    # Skip s3 tests if httpfs extension is unavailable
    try:
        duckdb.sql("install httpfs")
    except duckdb.Error as e:
        if 'Failed to download extension "httpfs"' in str(e):
            skip_s3 = pytest.mark.skip(
                reason="httpfs not available and is needed for setting s3 credentials"
            )

    # Skip ducklake tests if the extension is unavailable
    skip_ducklake = None
    try:
        duckdb.sql("install ducklake")
    except duckdb.Error as e:
        if "Failed to download extension" in str(e):
            skip_ducklake = pytest.mark.skip(reason="ducklake extension not available")

    if skip_s3 is not None:
        for item in items:
            if "with_s3_creds" in item.keywords:
                item.add_marker(skip_s3)

    if skip_ducklake is not None:
        for item in items:
            if "requires_ducklake" in item.keywords:
                item.add_marker(skip_ducklake)

import pytest
from unittest.mock import patch

from duckdb import IOException

from dbt.adapters.duckdb.credentials import DuckDBCredentials
from dbt.adapters.duckdb.credentials import Retries
from dbt.adapters.duckdb.environments import Environment

class TestConnectRetries:

    @pytest.fixture
    def creds(self):
        # Create a mock credentials object
        return DuckDBCredentials(
            path="foo.db",
            retries=Retries(connect_attempts=2, retryable_exceptions=["IOException", "ArithmeticError"])
        )

    @pytest.mark.parametrize("exception", [None, IOException, ArithmeticError, ValueError])
    def test_initialize_db(self, creds, exception):
        # Mocking the duckdb.connect method
        with patch('duckdb.connect') as mock_connect:
            if exception:
                mock_connect.side_effect = [exception, None]

            if exception == ValueError:
                with pytest.raises(ValueError) as excinfo:
                    Environment.initialize_db(creds)
            else:
                # Call the initialize_db method
                Environment.initialize_db(creds)
                if exception in {IOException, ArithmeticError}:
                    assert mock_connect.call_count == creds.retries.connect_attempts
                else:
                    mock_connect.assert_called_once_with(creds.path, read_only=False, config={})

import importlib
import inspect

import pytest

from dbt.adapters.duckdb.plugins import BasePlugin


def _import_plugin(module: str):
    try:
        return importlib.import_module(f"dbt.adapters.duckdb.plugins.{module}")
    except ImportError as e:
        pytest.skip(f"optional dependency unavailable for {module}: {e}")


@pytest.mark.parametrize("module", sorted(BasePlugin._BUILTIN))
def test_plugin_init_accepts_create_keywords(module):
    # BasePlugin.create calls mod.Plugin(name=..., plugin_config=..., credentials=...)
    plugin = _import_plugin(module)
    params = set(inspect.signature(plugin.Plugin.__init__).parameters)
    assert {"name", "plugin_config", "credentials"} <= params


class TestPostgresPlugin:
    def test_create_forwards_credentials(self, mocker):
        credentials = mocker.Mock()
        dsn = "postgresql://user:password@localhost:5432/mydb"

        plugin = BasePlugin.create(
            "postgres",
            config={"dsn": dsn},
            credentials=credentials,
        )

        assert plugin.name == "postgres"
        assert plugin._dsn == dsn
        assert plugin.creds is credentials

    def test_create_without_credentials(self):
        plugin = BasePlugin.create("postgres", config={"dsn": "postgresql://user@localhost/db"})

        assert plugin.creds is None

