            {
                "alias": "regular_db",
                "path": "/path/to/regular.db"
            }
        ]

        adapter = self._get_adapter(profile_cfg)
        relation = DuckDBRelation.create(database="regular_db", schema="test_schema", identifier="test_table")

        result = adapter.is_ducklake(relation)

